/**
@typedef {("inch" | "pica" | "point" | "em" | "pixel")} UnitType
@typedef {{
  unit?: UnitType,
  value?: number,
  px: number
}} Unit

*/
class ScaleEngine{
  constructor(scale = 1, viewport = 1){
    this.dpi = window.devicePixelRatio * 96
    this.scale = scale / this.dpi
  }

  /**
  @param {number} value 
  @returns {Unit} 
  */
  em(value){
    return {
      unit:"em",
      value,
      px: this.inch(value/6).px
    }
  }

  /**
  @param {number} value 
  @returns {Unit} 
  */
  px(value){
    return {
      unit: "pixel",
      value,
      px: value*this.scale
    }
  }

  /**
  @param {number} value 
  @returns {Unit} 
  */
  px_raw(value){
    return {
      unit: "pixel",
      value,
      px: value
    }
  }

  pixel(value){return this.px(value)}

  /**
  @param {number} value 
  @returns {Unit} 
  */
  inch(value){
    return { 
      unit: "inch",
      value,
      px: value * this.dpi * this.scale
    }
  }

  /**
  @param {number} value 
  @returns {Unit} 
  */
  pica(value){ return this.em(value) }
  picas(value){return this.pica(value)}


  /**
  @param {number} value 
  @returns {Unit} 
  */
  point(value){
    return {
      unit: "point",
      value,
      px: this.pica(value).px / 12
    }
  }

}

