/**
@typedef {{
  margin: {
    top: Unit,
    bottom: Unit,
    inside: Unit,
    outside: Unit,
  }

  columns: number,
  gutter: Unit,

  hanglines: Unit[]
  page_width: Unit,
  page_height: Unit,
}} GridProps

@param {GridProps} props
@param {ScaleEngine} s
*/
const Grid = (props, s) => {

  /**@returns {{x: Unit, y: Unit}}*/
  let half_page = () => {
    return {
      x: s.px_raw(props.page_width.px / 2),
      y: s.px_raw(props.page_height.px / 2)
    }
  }

  /**@returns {Unit}*/
  let column_size = () => {
    let w = half_page().x.px - (props.margin.inside.px + props.margin.outside.px);
    return s.px_raw( ((w - (props.gutter.px * (props.columns - 1))) / props.columns) );
  }

  /**@returns {{x:Unit, y:Unit, w:Unit, h: Unit}[]}*/
  let verso_columns = () => {
    /**@type {{x:Unit, y:Unit, w:Unit, h: Unit}[]}*/
    const cols = []

    for(let i = 0; i < props.columns; i++){
      const y = props.margin.top
      const w = column_size()

      // outside + gutters + size
      const x = s.px_raw(props.margin.outside.px + i * props.gutter.px + i * column_size().px);
      const h = s.px_raw(props.page_height.px - (props.margin.top.px + props.margin.bottom.px))

      cols.push({x, y, w, h })
    }

    return cols
  }

  /**@typedef {{x:Unit, y:Unit, w:Unit, h: Unit}} UnitRect*/
  /**@returns {UnitRect[]}*/
  let recto_columns = () => {
    /**@type {UnitRect[]}*/
    const cols = []

    for(let i = 0; i < props.columns; i++){
      const y = props.margin.top
      const w = column_size()

      // outside + gutters + size
      const x = s.px_raw(half_page().x.px + props.margin.inside.px + i * props.gutter.px + i * column_size().px);
      const h = s.px_raw(props.page_height.px - (props.margin.top.px + props.margin.bottom.px))

      cols.push({x, y, w, h })
    }

    return cols
  }

  /**@returns {[UnitRect[], UnitRect[]]}*/
  const columns = () => [verso_columns(), recto_columns()]

  return {verso_columns, recto_columns, column_size, half_page, columns}
}
